import{_ as t}from"./chunks/druid_integration.RlCeGZCB.js";import{_ as r,c as a,o as d,a2 as i}from"./chunks/framework.QTfwLiL8.js";const m=JSON.parse('{"title":"0006 Etcd Druid","description":"","frontmatter":{"github_repo":"https://github.com/gardener/enhancements","github_subdir":"geps/0006-etcd-druid","params":{"github_branch":"main"},"path_base_for_github_subdir":{"from":"content/docs/proposals/0006-etcd-druid/README.md","to":"README.md"},"title":"0006 Etcd Druid","prev":false,"next":false},"headers":[],"relativePath":"docs/proposals/0006-etcd-druid/index.md","filePath":"docs/proposals/0006-etcd-druid/index.md","lastUpdated":null}'),n={name:"docs/proposals/0006-etcd-druid/index.md"};function c(o,e,s,l,u,h){return d(),a("div",null,e[0]||(e[0]=[i('<h1 id="gep-0006-integrating-etcd-druid-with-gardener" tabindex="-1">GEP-0006: Integrating etcd-druid with Gardener <a class="header-anchor" href="#gep-0006-integrating-etcd-druid-with-gardener" aria-label="Permalink to &quot;GEP-0006: Integrating etcd-druid with Gardener&quot;">​</a></h1><p>etcd is currently deployed by garden-controller-manager as a Statefulset. The sidecar container spec contains details pertaining to cloud-provider object-store, which is injected into the statefulset via a mutable webhook running as part of the gardener extension <a href="https://github.com/gardener/gardener/tree/master/docs/extensions/controlplane-webhooks.md#what-needs-to-be-implemented-to-support-a-new-cloud-provider" target="_blank" rel="noreferrer">story</a>. This approach restricts the operations on etcd, such as scale-up and upgrade. etcd-druid will eliminate the need to hijack statefulset creation to add cloudprovider details. It has been designed to provide an intricate control over the procedure of deploying and maintaining etcd. The roadmap for etcd-druid can be found at the <a href="https://github.com/gardener/etcd-druid/issues/2" target="_blank" rel="noreferrer">gardener/etcd-druid</a> repository.</p><p>This document explains how Gardener deploys etcd and what resources it creates for etcd-druid to deploy an etcd cluster.</p><h2 id="resources-required-by-etcd-druid-created-by-gardener" tabindex="-1">Resources Required by etcd-druid (Created by Gardener) <a class="header-anchor" href="#resources-required-by-etcd-druid-created-by-gardener" aria-label="Permalink to &quot;Resources Required by etcd-druid (Created by Gardener)&quot;">​</a></h2><p>etcd-druid requires a:</p><ul><li>Secret containing credentials to access backup bucket in Cloud provider object store.</li><li>TLS server and client secrets for etcd and backup-sidecar.</li><li>etcd CRD resource that contains parameters pertaining to etcd, backup-sidecar, and cloud-provider object store.</li></ul><p>When an etcd resource is created in the cluster, the druid acts on it by creating an etcd statefulset, a service, and a configmap containing the etcd bootstrap script. The secrets containing the infrastructure credentials and the TLS certificates are mounted as volumes. If no secret/information regarding backups is stated, then etcd data backups are not taken. Only data corruption checks are performed prior to starting etcd.</p><p>Garden-controller-manager, being cloud agnostic, deploys the etcd resource. This will not contain any cloud-specific information other than the cloud-provider. The extension controller that contains the cloud specific implementation to create the backup bucket will create it if needed and create a secret containing the credentials to access the bucket. The etcd backup secret name should be exposed in the BackupEntry status. Then, Gardener can read it and write it into the ETCD resource. The secret will have to be made available in the namespace the etcd statefulset will be deployed. If etcd and backup-sidecar communicates over TLS then the CA certificates, server and client certificates, and keys will also have to be made available in the namespace as well. The etcd resource will have a reference to these aforementioned secrets. etcd-druid will deploy the statefulset only if the secrets are available.</p><h2 id="workflow" tabindex="-1">Workflow <a class="header-anchor" href="#workflow" aria-label="Permalink to &quot;Workflow&quot;">​</a></h2><ul><li>etcd-druid will be deployed and etcd CRD will be created as part of the seed bootstrap.</li><li>Garden-controller-manager creates a backupBucket extension resource. The extension controller creates the backup bucket associated with the seed.</li><li>Garden-controller-manager creates a backupentry associated with each shoot in the seed namespace.</li><li>Garden-controller-manager creates an etcd resource with secretRefs and etcd information populated appropriately.</li><li>etcd-druid acts on the etcd resource; druid creates the statefulset, the service, and the configmap.</li></ul><p><img src="'+t+'" alt="etcd-druid"></p>',11)]))}const f=r(n,[["render",c]]);export{m as __pageData,f as default};
